import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('passes valid input with an unlisted extra property through unchanged', async () => {
    const registry = new ToolRegistry();
    let capturedInput: any = null;

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {
            foo: {type: 'string'},
          },
          required: ['foo'],
        },
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    const input = {foo: 'bar', extra: 'baz'};
    await registry.execute('test_tool', input);

    // Use toEqual to ensure no extra properties were added (like defaults) or coerced
    // and that 'extra' is still there.
    expect(capturedInput).toEqual(input);
  });
});

