  it('resolves and validates against current schema for function-valued tool definitions', async () => {
    const registry = new ToolRegistry();
    let currentSchema: any = {type: 'object', properties: {foo: {type: 'string'}}, required: ['foo']};

    registry.register(
      () => ({
        name: 'dynamic',
        description: 'd',
        inputSchema: currentSchema,
      }),
      async () => 'ok'
    );

    // Call 1: valid for first schema
    const r1 = await registry.execute('dynamic', {foo: 'v'});
    expect(r1.result).toBe('ok');

    // Change schema object
    currentSchema = {type: 'object', properties: {bar: {type: 'string'}}, required: ['bar']};

    // Call 2: invalid for second schema (old 'foo' is now extra, 'bar' is missing)
    const r2 = await registry.execute('dynamic', {foo: 'v'});
    expect(r2.result).toContain('bar');
    expect(r2.result).toContain('required');

    // Call 3: valid for second schema
    const r3 = await registry.execute('dynamic', {bar: 'v'});
    expect(r3.result).toBe('ok');
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow(/Unknown tool: missing/);
  });
});

